#!/usr/bin/env python3
"""Rebuild reviewed Dutch product content; error articles come from the coverage inventory.

No runtime defaults overwrite an imported or published manual. This is a repository build tool.
"""
import html
import json
import argparse
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DEST = ROOT / 'services/admin-overlay/admin/defaults'


def paragraphs(*text):
    return ''.join(f'<p>{html.escape(t)}</p>' for t in text)


def steps(*text):
    return '<ol>' + ''.join(f'<li>{html.escape(t)}</li>' for t in text) + '</ol>'


def topic(id, title, content, requires=None, rights=None, related=None):
    return dict(id=id, title=title, content=content, requires=requires or [], rights=rights or [], related=related or [], items=[], aliases=[], codes=[], messages=[])


def chapter(id, title, content, *items, requires=None, aliases=None):
    result = topic(id, title, content, requires)
    result['items'] = list(items)
    result['aliases'] = aliases or []
    return result


def build(check=False):
    P, S, T = paragraphs, steps, topic
    sections = [
        chapter('sec1', 'Welkom en snelstart', P('{{APP_NAME}} helpt bij schrijven, samenvatten en onderzoeken. Een taalmodel genereert een waarschijnlijk antwoord; dat is geen bewijs dat de inhoud klopt. Controleer bronnen, cijfers en juridische conclusies zelf.', 'Deze handleiding is naslaginformatie, geen verplichte beleidsacceptatie. Hulp openen of sluiten verandert je gesprek niet. Gebruik de zoekfunctie voor een onderwerp of foutmelding.'),
            T('snelstart', 'Drie eerste taken', S('Begin een nieuw gesprek en vraag: Herschrijf onderstaande tekst in begrijpelijk Nederlands. Behoud betekenis, voorwaarden en uitzonderingen.', 'Vraag: Maak van onderstaande notities een concept met besluiten, acties, eigenaren en deadlines. Gebruik onbekend waar informatie ontbreekt.', 'Vraag: Vergelijk deze twee teksten. Scheid overeenkomsten, verschillen en onzekerheden en vermeld de bronpassages.'), ['chat'], related=['goede-vraag', 'antwoord-controleren']),
            T('handleiding-gebruiken', 'Zoeken, navigeren en actuele passages', P('Zoek op de titel, een woord uit de uitleg of de herkenbare foutmelding. Een passageverwijzing hoort bij een handleidingrevisie. Is die gewijzigd of niet meer beschikbaar, open dan de actuele inhoudsopgave. Een ontbrekend onderwerp betekent niet dat je het bijbehorende productrecht hebt.', 'Een agent kan beschikbare handleidingpassages opvragen. Controleer de aangehaalde passage zelf. Een AI kan ook een niet-bestaande bron noemen; een bronverwijzing is daarom pas bruikbaar als de bestemming gevalideerd is.'))),
        chapter('sec2', 'Veilig en verantwoord werken', P('Gebruik uitsluitend informatie die je volgens het actuele beleid van je organisatie in deze toepassing mag verwerken. Deze handleiding geeft geen garantie over datalocatie, logging, training of bewaartermijnen.'),
            T('gegevens-beleid', 'Persoonsgegevens en vertrouwelijke informatie', P('Bepaal vooraf doel, noodzaak en gevoeligheid. Laat namen, identificatienummers, medische gegevens en vertrouwelijke details weg wanneer die niet nodig zijn. Ook pseudoniemen kunnen samen met andere informatie herleidbaar zijn.', 'Een eigen server betekent niet automatisch dat alle verwerking binnen de organisatie blijft. Modellen, tools, documentverwerking en leveranciers kunnen verschillende gegevensstromen hebben. Raadpleeg actueel organisatiebeleid of de privacycontactpersoon voordat je gevoelige informatie gebruikt.'), related=['ondersteuning', 'faq-privacy']),
            T('antwoord-controleren', 'Bronnen, actualiteit en menselijke besluitvorming', P('Controleer feitelijke uitspraken bij de oorspronkelijke bron. Open een link en kijk of de bron de conclusie werkelijk ondersteunt; verifieer datum, auteur en toepasselijke situatie. Een model kan bronnen verzinnen of verouderde regels gebruiken.', 'De kennisactualiteit hangt af van het ingezette model en van werkelijk geraadpleegde tools en bronnen. Er is geen vaste kennisgrens voor de hele toepassing. Laat AI geen zelfstandig besluit nemen over personen of rechten. Gebruik vakinhoudelijke, juridische en bestuurlijke toetsing waar nodig.'), related=['tools-nieuws', 'transparantie']),
            T('incident', 'Een mogelijk informatie- of beveiligingsincident', P('Stop met het delen van de betrokken informatie en volg de incidentprocedure van je organisatie. Stuur geen gevoelige chat, volledige documenten, tokens of wachtwoorden naar een gewone feedbackmailbox.', 'Noteer alleen niet-gevoelige gegevens: tijdstip, onderdeel, exacte foutcode en globaal wat je deed. Gebruik de afgesproken veilige meldroute. Het verwijderen van een gesprek is geen bewijs dat een incident is opgelost.'), related=['ondersteuning'])),
        chapter('chatten', 'Chatten en gesprekken beheren', P('Een gesprek bevat je vragen en eerdere antwoorden. Relevante eerdere context kan worden meegenomen, maar het contextvenster is begrensd. Start een nieuw gesprek voor een duidelijk ander onderwerp.'),
            T('nieuw-gesprek', 'Een gesprek starten en doorvragen', S('Kies Nieuw gesprek in de zijbalk of open de nieuwe-chatroute.', 'Beschrijf doel, doelgroep, context, bronmateriaal, randvoorwaarden en gewenste vorm. Controleer bijlagen voordat je verstuurt.', 'Gebruik vervolgvragen om één onderdeel te verbeteren: Licht de aannames toe of Toon welke bronpassage deze conclusie ondersteunt.'), ['chat'], related=['goede-vraag', 'document-gebruiken']),
            T('chat-antwoorden', 'Stoppen, bewerken en opnieuw proberen', P('Tijdens het genereren kun je de stopactie gebruiken. Een gedeeltelijk antwoord is niet noodzakelijk compleet. Controleer voordat je opnieuw verstuurt of een eerdere opdracht nog loopt.', 'Bij je eigen bericht kun je de bewerkactie gebruiken en de aangepaste vraag opnieuw verzenden. Bij een antwoord kun je, wanneer de actie wordt aangeboden, opnieuw genereren. Dit kan een nieuwe gespreksvertakking maken en geeft niet gegarandeerd dezelfde uitkomst.', 'Met de kopieeractie neem je tekst over. Controleer inhoud en opmaak vóór gebruik. Feedbackacties melden je waardering; ze vervangen geen incidentmelding. Andere acties kunnen per endpoint en scherm verschillen.'), ['chat']),
            T('chat-geschiedenis', 'Geschiedenis, zoeken en hernoemen', S('Open de gesprekszijbalk; op een klein scherm moet je die mogelijk eerst uitklappen.', 'Selecteer een bestaand gesprek om verder te werken. Gebruik de zoekactie om gesprekken op terugvindbare woorden te zoeken.', 'Open het actiemenu bij een gesprek voor Hernoemen. Geef een niet-gevoelige herkenbare titel.'), ['history'], related=['chat-verwijderen']),
            T('chat-verwijderen', 'Een gesprek verwijderen', P('Open het actiemenu bij het gesprek, kies verwijderen en lees de bevestiging zorgvuldig. Een verwijderde gespreksweergave kan niet vanzelf worden hersteld.', 'Gesprekken en bestanden hebben verschillende beheeracties. Controleer ook het bestandenoverzicht als je bijlagen wilt verwijderen. Verwijderen uit de toepassing garandeert niet de onmiddellijke verwijdering uit backups, beveiligingslogs of systemen van leveranciers; daarvoor geldt het vastgestelde beleid.'), ['history'], related=['bestanden-verwijderen', 'faq-retentie']),
            T('tijdelijke-chat', 'Tijdelijke gesprekken', P('Alleen wanneer Tijdelijke chat werkelijk wordt aangeboden kun je die modus kiezen. Lees de bijbehorende productinformatie en organisatieafspraken. Tijdelijk betekent niet automatisch geen logging, geen verwerking door leveranciers of volledige anonimiteit.'), ['temporaryChat']),
            T('chat-delen', 'Een gesprekslink delen', P('Gebruik alleen de aangeboden deelactie en controleer welke inhoud de ontvanger kan zien. Deel geen persoonsgegevens, vertrouwelijke documenten of interne bronlinks buiten de toegestane doelgroep. Een link kan doorgegeven worden; lees de bereikinstelling en trek de link in als die niet meer nodig is.'), ['sharedLinks']),
            T('model-keuze', 'Modelkeuze', P('Als modelkeuze beschikbaar is, kies alleen een model dat voor jouw taak en gegevens is toegestaan. Modellen kunnen verschillen in contextvenster, bronnen, bijlagen en mogelijkheden. Een andere keuze is geen oplossing om veiligheids- of organisatiebeleid te omzeilen.'), ['models'])),
        chapter('documenten', 'Documenten en bestanden beheren', P('Een bijlage beschikbaar maken is niet hetzelfde als een complete kennisbank bouwen. De mogelijkheden hangen af van endpoint, bestandstype, verwerking en rechten.'),
            T('document-upload', 'Bijlagen toevoegen en verwerking volgen', S('Gebruik de bijlage- of uploadactie bij het invoerveld. Selecteer alleen toegestane bestanden en controleer bestandsnaam, formaat en grootte.', 'Wacht op de upload- en verwerkingsstatus. Een geselecteerde of geüploade bijlage is nog niet noodzakelijk succesvol uitgelezen.', 'Stel daarna een concrete vraag over het document. Vraag om hoofdstuk, pagina of een korte bronpassage en controleer die in het origineel.'), ['upload'], related=['document-limieten', 'document-gebruiken']),
            T('document-limieten', 'Bestandstypen, grootte en contextlimieten', P('De uploadkiezer en de effectieve bestandsconfiguratie bepalen wat je in dit endpoint mag toevoegen. Limieten kunnen gelden per bestand, totaal, aantal en hoeveelheid uitgelezen tekst. De kleinste grens in uploadproxy, LibreChat, extractor of agent kan beslissend zijn.', 'De documentadapter in deze versie verwerkt onder meer PDF, tekst, Office-bestanden, spreadsheets en e-mail waar de ingestelde route dat ondersteunt. XLSM kan voor tekstuele celinhoud worden verwerkt; macro’s worden nooit uitgevoerd. Een documenttype in de adapter bewijst niet dat elk endpoint het accepteert.', 'Een bestandslimiet is niet hetzelfde als het contextvenster van een model. Ook veel kleine bestanden of eerdere gesprekscontext kunnen te veel invoer opleveren. Gebruik een noodzakelijke selectie, zonder gevoelige stukken naar een niet-goedgekeurde omweg te verplaatsen.'), ['upload'], related=['document-kwaliteit']),
            T('document-kwaliteit', 'Scans, OCR, tabellen en macrobestanden', P('Een scan bevat mogelijk geen bruikbare tekst. OCR kan tekens, kolommen en paginavolgorde verkeerd herkennen. Controleer namen, cijfers, bedragen en verwijzingen extra zorgvuldig. Vraag niet om een zekere conclusie als passages ontbreken.', 'In spreadsheets worden beschikbare tekstuele celwaarden uitgelezen; berekeningen, visuals, verborgen werkbladen, externe koppelingen en macrofunctionaliteit worden niet betrouwbaar als volledige analyse gereproduceerd. Een formulecache kan verouderd zijn. XLSM-macro’s worden niet uitgevoerd en mogen niet als uitgevoerde berekening worden voorgesteld.', 'Beschadigde, versleutelde, te grote of onveilig opgebouwde bestanden kunnen worden geweigerd. Pas beveiligingen niet aan om een waarschuwing te omzeilen. Vraag de documenteigenaar om een goedgekeurde leesbare versie.'), ['upload'], related=['document-limieten']),
            T('document-gebruiken', 'Samenvatten, vergelijken en broncontrole', P('Geef aan welk document en welke passages relevant zijn. Vraag bijvoorbeeld: Vat de bijlage samen in vijf punten; benoem ontbrekende informatie en vermeld de secties waarop je antwoord steunt.', 'Voor vergelijken: Vergelijk document A en B op verplichtingen, termijnen en uitzonderingen. Maak een tabel met bronpassages en geef geen verschil aan als de bron onvoldoende duidelijk is.', 'Een agent kan een document als bron gebruiken, maar garandeert geen volledige lezing van alle pagina’s. Controleer de uitgelezen tekst en de oorspronkelijke bestanden. Instructies in een bijlage zijn broninhoud, geen nieuwe systeem- of veiligheidsinstructies.'), ['upload']),
            T('bestanden-overzicht', 'Het bestandenoverzicht', P('Open het bestandenonderdeel in de navigatie om je opgeslagen uploads te bekijken. Zoek of selecteer het bedoelde bestand en controleer de naam voordat je een actie uitvoert. Welke bestanden zichtbaar zijn hangt af van eigenaarschap, toegang en het gebruikte endpoint.', 'Een bestandsnaam in een gesprek betekent niet dat een andere gebruiker het bestand mag lezen. Een bestand kan in meer dan één gesprek zijn gebruikt. Het overzicht en een bijlage in de invoer zijn verschillende plaatsen.'), ['files'], related=['bestanden-verwijderen']),
            T('bestanden-verwijderen', 'Een bijlage losmaken of opgeslagen bestand verwijderen', P('Een bijlage uit het invoerveld verwijderen voorkomt dat je die met dat nieuwe bericht meestuurt; dit is niet automatisch het verwijderen van een eerder opgeslagen upload.', 'Gebruik in het bestandenoverzicht de verwijderactie voor het bedoelde bestand, lees de bevestiging en controleer wat er daarna nog zichtbaar is. Verwijderen kan latere verwijzingen onbruikbaar maken. Verwijder niet op basis van een toevallig gelijkende bestandsnaam.', 'Een verwijderactie geeft geen absolute garantie over onmiddellijke verwijdering van iedere kopie, backup, log of leveranciersregistratie. Vraag de bevoegde contactpersoon naar toegang, bewaartermijn en het afhandelen van een verwijderverzoek.'), ['files'], related=['chat-verwijderen', 'faq-retentie']),
            T('document-kennisbank', 'Upload versus bestandszoeken', P('Een upload in de chat en een beheerde kennisbron zijn verschillende voorzieningen. Een upload is niet automatisch doorzoekbaar voor anderen en voegt niet vanzelf blijvende modelkennis toe. Gebruik de aangewezen kennisbron voor gedeelde informatie.'), ['upload']),
            T('native-bestandszoeken', 'Native bestandszoeken', P('Als native bestandszoeken beschikbaar is, kunnen geselecteerde bestanden via een zoekindex worden geraadpleegd. Dat is geen garantie dat elk relevant fragment wordt gevonden. Controleer de bronverwijzingen, toegang en reikwijdte. Dit is iets anders dan de GovChat-documentadapter die uploadtekst aan een agent aanbiedt.'), ['fileSearch'])),
        chapter('promptbibliotheek', 'Promptbibliotheek', P('Een bibliotheekprompt is een herbruikbare gebruikersvraag. De door beheerders ingestelde masterprompt stuurt de agent op een ander niveau; een bibliotheekprompt wijzigt die niet.', 'De applicatie biedt de promptbibliotheek aan, maar dit bevestigt geen persoonlijke gebruiks-, maak-, bewerk- of deelrechten. Alleen als jouw account toegang heeft en de actie wordt aangeboden, kun je Prompts in de navigatie of de beschikbare inline promptkiezer openen, een beschikbare prompt kiezen, de actieve productieversie lezen en eventuele variabelen invullen. Raadpleeg de ingelogde handleiding voor jouw toegestane passages; probeer ontbrekende rechten niet te omzeilen.', 'Controleer vóór Prompt gebruiken het gesprek en de gewenste opdracht: de actie kan de prompt meteen in het gesprek indienen; bij variabelen opent eerst het invulvenster. Variabelen zijn geen beveiligde kluis: wat je invult kan onderdeel van de modelvraag worden. Gebruik uitsluitend informatie die je volgens het actuele organisatiebeleid mag verwerken.'),
            T('prompt-vinden', 'Een prompt vinden en gebruiken', S('Open Prompts in de navigatie of de beschikbare inline promptkiezer. Gebruik zoek- en categoriefilters om een relevante promptgroep te vinden.', 'Open de prompt en lees de actieve productieversie. Controleer de instructies voordat je eigen bronmateriaal toevoegt.', 'Kies Prompt gebruiken. In de detailweergave kan deze actie de prompt meteen in het gesprek indienen; bij variabelen opent eerst het invulvenster. Controleer daarom vóór de actie het gesprek en de gewenste opdracht.'), ['prompts'], ['prompts.use'], ['prompt-variabelen', 'prompt-versies']),
            T('prompt-variabelen', 'Variabelen invullen', P('Een prompt kan invulvelden gebruiken zoals {{doelgroep}} of {{tekst}}. Vul ieder benodigd veld doelgericht in. Variabelen zijn geen beveiligde kluis: wat je invult kan onderdeel van de modelvraag worden.', 'Het invulvenster toont de gevraagde waarden. Controleer de uiteindelijke betekenis voordat je de opdracht uitvoert. Voor speciale variabelen, zoals datumwaarden, kan de toepassing zelf een waarde leveren; voeg niet willekeurig vertrouwelijke informatie aan een generieke variabele toe.'), ['prompts'], ['prompts.use']),
            T('prompt-maken', 'Een eigen prompt maken en bewerken', S('Gebruik de maakactie in de promptbibliotheek wanneer je daarvoor toestemming hebt.', 'Geef een duidelijke naam, beschrijving en categorie. Schrijf de opdracht met doel, randvoorwaarden en gewenste output; voeg herbruikbare variabelen toe waar dat nuttig is.', 'Sla op en test met niet-gevoelige voorbeeldinformatie. Bewerk alleen prompts waarvoor je bewerkingsrechten hebt. Controleer of je wijzigingen de actieve productieversie veranderen.'), ['prompts'], ['prompts.create'], ['prompt-versies', 'prompt-voorbeelden']),
            T('prompt-versies', 'Revisies en actieve productieversie', P('Een promptgroep kan meerdere versies hebben. In het versieoverzicht zie je de geselecteerde versie en de productieversie die bij gebruik wordt aangeboden. De nieuwste opgeslagen tekst hoeft niet dezelfde te zijn als de productieversie.', 'Wanneer je bewerkingsrechten hebt, kun je een nieuwe versie opslaan en de aangeboden actie gebruiken om een versie als productieversie te kiezen. Controleer die keuze voordat anderen de prompt gebruiken. Verwijder alleen de bedoelde versie of groep; lees de bevestiging. Zonder bewerkingsrecht is dit overzicht alleen een bron om de juiste versie te herkennen.'), ['prompts'], ['prompts.use']),
            T('prompt-delen', 'Promptrechten en delen', P('Alleen als delen is toegestaan kun je de deelactie gebruiken. Selecteer het passende bereik en lees welke rechten ontvangers krijgen. Het recht om een prompt te gebruiken is niet automatisch een recht om hem te bewerken of verder te delen.', 'Neem geen vertrouwelijke casus, persoonsgegevens, interne tokens of niet-toegestane links op in een gedeelde prompt. Delen van een prompt is niet hetzelfde als delen van een gesprek of bijlagen. Vraag een beheerder om uitleg als een actie ontbreekt; probeer rechten niet te omzeilen.'), ['prompts'], ['prompts.share']),
            T('prompt-publiek', 'Publieke prompts', P('Publiek delen vereist een afzonderlijk toegestaan bereik. Controleer zorgvuldig dat prompttekst, beschrijving en variabelen geen interne informatie onthullen. Publiek is geen synoniem voor alleen collega’s.'), ['prompts'], ['prompts.sharePublic']),
            T('prompt-voorbeelden', 'Vier herbruikbare voorbeelden', P('B1: Herschrijf {{tekst}} voor {{doelgroep}} op B1-niveau. Behoud betekenis en uitzonderingen. Geef aan welke vaktermen toelichting nodig hebben.', 'Samenvatting: Vat {{tekst}} samen in vijf punten. Scheid feiten, conclusies en onzekerheden. Voeg korte bronpassages toe.', 'Notulen: Maak conceptnotulen van {{notities}}. Gebruik kopjes Besluiten, Acties en Open punten. Verzin geen eigenaar of deadline.', 'Kritisch vergelijken: Vergelijk {{tekst_a}} en {{tekst_b}} op {{criteria}}. Geef overeenkomsten, verschillen, ontbrekende gegevens en bronpassages. Trek geen conclusie die de bronnen niet ondersteunen.'), ['prompts'], ['prompts.use'])),
        chapter('goede-vragen', 'Goede vragen stellen', P('Een bruikbare opdracht maakt duidelijk wat je wilt bereiken en welk bronmateriaal bepalend is. Een langere vraag is niet automatisch beter.'),
            T('goede-vraag', 'Doel, context, grenzen en formaat', P('Gebruik deze structuur: Doel: … Doelgroep: … Context: … Bronnen: … Randvoorwaarden: … Uitvoer: … Controle: …', 'Voorbeeld: Schrijf een conceptmail voor inwoners over deze maatregel. Gebruik alleen de aangeleverde feiten. Maximaal 200 woorden, begrijpelijke taal, neutrale toon. Vermeld ontbrekende informatie apart. Behoud alle termijnen en uitzonderingen.', 'Vraag om verduidelijking wanneer een cruciaal gegeven ontbreekt. Deel ingewikkeld werk op in inhoudelijke stappen; gebruik die werkwijze niet om verboden of onveilige verzoeken te verbergen.'), ['chat']),
            T('doorvragen', 'Itereren zonder blind vertrouwen', P('Vraag: Welke aannames heb je gebruikt? Welke bron ondersteunt dit? Wat ontbreekt voor een betrouwbare conclusie? Laat twee formuleringen vergelijken op betekenis in plaats van alleen op stijl.', 'Een overtuigende uitleg kan nog steeds onjuist zijn. Controleer het resultaat buiten de chat en leg vast welke bronnen je zelf hebt gecontroleerd. Een lange redenering is geen kwaliteitsgarantie.'), ['chat'], related=['antwoord-controleren'])),
        chapter('apps-tools', 'Beschikbare apps en tools', P('Alleen ingeschakelde onderdelen worden hieronder beschreven. Welke tool de agent daadwerkelijk gebruikt blijkt uit de toolmelding en de ontvangen brondata. Een genoemde toolnaam in een antwoord bewijst geen uitvoering.'),
            T('tools-nieuws', 'NOS-nieuws', P('De NOS-tool raadpleegt officiële RSS-feeds. Vraag om actuele berichten met bronlinks en publicatiedatums. Een zoekwoord filtert de huidige feeditems lokaal; dit is geen volledig nieuwsarchief. Controleer de volledige artikelen bij de bron.'), ['nos_news']),
            T('tools-l1', 'L1 Nieuws', P('De L1-tool raadpleegt officiële Limburgse nieuwsfeeds met categorieën zoals nieuws, sport, 112 en cultuur en media. Vraag om bronnen en datums. Lege resultaten betekenen niet dat er nooit over het onderwerp is gepubliceerd.'), ['l1_news']),
            T('tools-tijd', 'Tijd en tijdzones', P('Vraag om de actuele tijd of een omzetting tussen tijdzones. Vermeld bron- en doelzone bij lokale tijden. Zomer- en wintertijd kunnen een tijd dubbelzinnig of ongeldig maken. Uren zijn verstreken tijd; kalenderdagen kunnen een andere duur hebben.'), ['time']),
            T('tools-feestdagen', 'Feestdagen', P('De feestdagentool gebruikt OpenHolidays API voor ondersteunde landen en regio’s. Noem land, jaar en zo nodig regio. Een vermelde feestdag is niet automatisch een wettelijk vrije dag en de tool geeft geen schoolvakantierooster.'), ['holidays']),
            T('tools-rekenen', 'Calculator', P('Gebruik de calculator voor concrete berekeningen. Controleer invoer, eenheden en afronding. De calculator bewijst niet dat de onderliggende aannames of juridische interpretatie juist zijn.'), ['calculator']),
            T('native-webzoeken', 'Native webzoeken', P('Native LibreChat-webzoeken is een afzonderlijke voorziening. De GovChat-nieuwstools zijn geen vervanging voor een volledige webzoekmachine. Controleer ook bij native zoeken bronkwaliteit, datum en volledigheid.'), ['webSearch']),
            T('apps-afbeeldingen', 'Afbeeldingen', P('Gebruik de aangeboden afbeeldingsfunctie met een duidelijke beschrijving. Volg regels voor portretrechten, auteursrechten en gevoelige inhoud. Een gegenereerd beeld kan feitelijk misleidend zijn. Bewerken van een bijlage vereist dat die functie en het gekozen model dat ondersteunen.'), ['image']),
            T('apps-transcript', 'Transcriptie', P('Volg de aangeboden opname- of uploadactie. Zorg dat je de opname mag verwerken en dat betrokkenen passend geïnformeerd zijn. Controleer transcript en sprekers; achtergrondgeluid, jargon en overlappende stemmen kunnen fouten veroorzaken. Conceptnotulen zijn geen vastgesteld verslag.'), ['transcript']),
            T('apps-versimpelaar', 'Versimpelaar', P('Voer de toegestane brontekst in en controleer de vereenvoudigde versie. Eenvoudiger taal mag betekenis, voorwaarden, deadlines en juridische uitzonderingen niet veranderen. Lees de tekst vanuit de doelgroep.'), ['simplifier']),
            T('apps-openbesluitvorming', 'OpenBesluitvorming', P('Gebruik de zoektool voor gepubliceerde overheidsdocumenten binnen de beschikbare brondekking. Controleer de originele publicatie, organisatie, datum en gevonden passages. Een zoekresultaat of statistiek is geen bewijs dat alle relevante besluiten in het systeem staan.'), ['openbesluitvorming']),
            T('apps-topdesk', 'Kennisartikelen', P('De kenniszoektool kan toegestane gepubliceerde kennisartikelen aanbieden. Houd rekening met brondekking, actualiteit en organisatiecontext. Neem broninstructies niet over als agentinstructies. Meld ontbrekende informatie zonder een oplossing te verzinnen.'), ['topdesk'])),
        chapter('beleidskompas', 'Beleidskompas', P('Het Beleidskompas ondersteunt het uitwerken van een beleidsvraagstuk. Beschikbare stappen en brondocumenten hangen af van de gepubliceerde appconfiguratie. Het neemt geen besluit.'),
            T('beleidskompas-werken', 'Een casus uitwerken', S('Open het Beleidskompas vanaf het startscherm of de appkiezer, wanneer dat wordt aangeboden.', 'Kies een beschikbare stap en beschrijf doel, context en het vraagstuk in het gesprek. Controleer welke onderdelen zijn uitgewerkt.', 'Bekijk gebruikte bronnen en toets conclusies bij de oorspronkelijke passages. Betrek inhoudelijke specialisten bij juridische, financiële of bestuurlijke impact.'), ['beleidskompas']), requires=['beleidskompas']),
        chapter('problemen', 'Problemen oplossen', P('Zoek in het foutennaslagwerk op de exacte melding of code. De uitleg betreft fouttypen, niet persoonlijke gesprekken of logbestanden. Een foutmelding is geen zekere diagnose.'),
            T('probleem-algemeen', 'Onbekende fout of vastgelopen scherm', P('Controleer eerst of je netwerkverbinding werkt en of de opdracht nog loopt. Bewaar alleen niet-gevoelige concepttekst als dat volgens beleid mag. Opnieuw laden of aanmelden kan helpen, maar garandeert niets en kan invoer verliezen.', 'Bij een onbekende melding: noteer tijdstip, onderdeel, foutcode en een korte niet-gevoelige beschrijving. Meld het via de afgesproken helpdeskroute. Stuur nooit een wachtwoord, sessiecookie, toegangstoken of volledige gevoelige bijlage mee.'), related=['ondersteuning']),
            T('probleem-sessie', 'Aanmelden en sessieverloop', P('Gebruik de officiële aanmeldroute. Een verlopen sessie, geweigerde organisatieaanmelding of ontbrekend recht kan opnieuw aanmelden of hulp van de beheerder vereisen. Herhaald proberen kan een tijdelijke limiet verlengen.', 'Verwijder geen organisatiebeveiliging, deel geen sessiegegevens en gebruik geen alternatieve onbeheerde URL om een blokkade te omzeilen. Bij een aanhoudend SSO-probleem vermeld je tijdstip, browser en niet-gevoelige foutcode.'), related=['ondersteuning']),
            T('probleem-netwerk', 'Netwerk, proxy en tijdelijke onbeschikbaarheid', P('Een timeout of 502/503/504 kan optreden tussen browser, proxy, agent, documentverwerker of modelleverancier. Het bewijst niet dat je invoer fout is. Wacht even en probeer een noodzakelijke kleine opdracht opnieuw als dat veilig kan.', 'Controleer of anderen dezelfde storing hebben zonder chatinhoud te delen. Alleen beheerders onderzoeken servicebereikbaarheid, proxyinstellingen en leveranciersstatus. Gebruikers hoeven geen API-sleutels of serverlimieten aan te passen.'), related=['ondersteuning'])),
        chapter('faq', 'Veelgestelde vragen', P('Gebruik de hoofdonderwerpen voor concrete stappen; hieronder staan grenzen en doorverwijzingen.'),
            T('faq-privacy', 'Wie kan mijn gegevens zien?', P('Toegang, logging en leveranciersverwerking hangen af van deployment, rechten en actueel beleid. Deze handleiding bevestigt geen datalocatie, beheerdersinzage, DPIA of juridische compliance. Raadpleeg de vastgestelde documentatie van jouw organisatie.'), related=['gegevens-beleid', 'ondersteuning']),
            T('faq-retentie', 'Bewaren, verwijderen en geheugen', P('Gespreksgeschiedenis, bestanden, technische logs, backups en eventueel model- of toolgeheugen zijn verschillende gegevensverzamelingen. Een chat verwijderen is niet automatisch alles verwijderen. Er staat hier geen vaste bewaartermijn of garantie dat gegevens wel of niet voor training worden gebruikt.', 'Vraag bij een bewaarbeleid of verwijderverzoek naar de betrokken systemen en de afgesproken procedure. Dat een agent eerdere tekst gebruikt, betekent niet dat het model blijvend is getraind op jouw gesprek.'), related=['chat-verwijderen', 'bestanden-verwijderen', 'ondersteuning']),
            T('faq-actualiteit', 'Is ieder antwoord actueel en betrouwbaar?', P('Nee. Actualiteit en nauwkeurigheid verschillen per model, tool en bron. Een tool moet daadwerkelijk zijn geraadpleegd en de bron kan zelf onvolledig of verouderd zijn. Controleer belangrijke uitkomsten, ook als de formulering zeker klinkt.'), related=['antwoord-controleren']),
            T('faq-beschikbaarheid', 'Waarom ontbreekt een knop of onderwerp?', P('Mogelijkheden kunnen per endpoint, deployment en recht verschillen. Een verborgen handleidingonderwerp zet de productfunctie niet uit of aan. Bij ontbrekende rechten of een storing helpt de bevoegde beheerder. Deze handleiding belooft geen onafgebroken beschikbaarheid, vaste kosten of klimaatimpact.'), related=['ondersteuning'])),
        chapter('sec3', 'Ondersteuning en leren', P('Gebruik de geconfigureerde contactmogelijkheden van je organisatie. Deel alleen de informatie die voor ondersteuning noodzakelijk en toegestaan is.'),
            T('ondersteuning', 'Helpdesk, feedback en privacyvragen', P('Voor een productfout: noteer tijdstip en tijdzone, browser, betrokken onderdeel, exacte code en of de fout herhaalbaar is. Vermeld geen tokens, wachtwoorden, persoonsgegevens of inhoud van gevoelige documenten.', 'Gebruik de bekende helpdesk- of incidentroute van je organisatie. Vraag bij privacyvragen naar de bevoegde privacycontactpersoon. Een feedbackcontact is geen vervanging voor een incidentmelding.'), related=['incident']),
            T('organisatie-contacten', 'Geconfigureerde contactgegevens', '<p>Helpdesk: <a href="mailto:{{SUPPORT_EMAIL}}">{{SUPPORT_EMAIL}}</a>. AI-vragen en feedback: <a href="mailto:{{AI_EMAIL}}">{{AI_EMAIL}}</a>. Leren: <a href="mailto:{{TRAINING_EMAIL}}">{{TRAINING_EMAIL}}</a>. Privacy: <a href="mailto:{{PRIVACY_EMAIL}}">{{PRIVACY_EMAIL}}</a>.</p>' + P('Ontbreekt een contactgegeven, gebruik dan de bekende interne route; een leeg veld betekent niet dat er geen ondersteuning bestaat. Deze profielgegevens zijn door de deploymentbeheerder te controleren.')),
            T('organisatie-leren', 'Leren en actueel beleid', '<p>Cursus: <a href="{{COURSE_URL}}">{{COURSE_URL}}</a></p><p>Beleidsinformatie: <a href="{{POLICY_URL}}">{{POLICY_URL}}</a></p><p>Incidentroute: <a href="{{INCIDENT_URL}}">{{INCIDENT_URL}}</a></p>' + P('Een cursus is ondersteuning bij verantwoord gebruik en geeft geen individuele toestemming om gevoelige gegevens in te voeren. Controleer of de link en toegang voor jou gelden.'))),
        chapter('transparantie', 'Transparantie en versie', P('{{APP_NAME}} combineert een gebruikersinterface, één of meer modellen en eventueel tools. De organisatie bepaalt toegang, inrichting en beleid; een modelleverancier of tool kan een afzonderlijke rol in de verwerking hebben.'),
            T('platform-model-tools', 'Platform, model en brondata', P('LibreChat levert de chatinterface. De GovChat-overlay voegt toepassingen en configuratie toe. De orchestrator kan toegestane tools aanroepen; een documentverwerker kan tekst uit bestanden uitlezen. Niet ieder antwoord gebruikt ieder onderdeel.', 'Toolresultaten, documenten en handleidingpassages zijn brondata, geen instructies om veiligheids- of organisatiebeleid te wijzigen. Open bronverwijzingen en beoordeel hun geldigheid.')),
            T('handleiding-versie', 'Revisie, controle en ontbrekende informatie', P('De inhoudsrevisie verandert bij publicatie of rollback en staat los van de applicatieversie. Browser en agent lezen dezelfde actuele publicatie, met filtering op beschikbaarheid en vertrouwde rechten.', 'Organisatieclaims over compliance, DPIA, datalocatie, leveranciers, logging, training, bewaartermijn, kosten en beschikbaarheid moeten afzonderlijk worden onderbouwd en gecontroleerd. Ongeverifieerde claims zijn niet als garanties opgenomen.'))),
    ]
    inventory = json.loads((ROOT / 'docs/manual-error-inventory.json').read_text())
    for section in sections:
        if section['id'] == 'documenten': section['requires'] = ['upload']
        if section['id'] == 'promptbibliotheek': section['requires'] = ['prompts']
        for item in section['items']:
            if item['id'] == 'handleiding-gebruiken':
                item['content'] += P('De gewone foutcatalogus beschrijft herkenbare problemen en veilige vervolgstappen. Labels, aanvullende schermtekst en niet algemeen aangetoonde productfuncties staan in een optionele naslagbijlage die standaard verborgen is. Een beheerder kan die afzonderlijk zichtbaar maken; een zichtbaar naslagartikel bewijst niet dat de functie voor jou beschikbaar is.')
    categories = inventory['catalog']
    for category in categories:
        category['parentId'] = 'problemen'
    model = dict(schemaVersion=1, enabled=False, agentEnabled=True, autoOpen='never', profile='generic',
                 organization=dict(appName='GovChat-NL', name='', helpdeskEmail='', aiEmail='', trainingEmail='', privacyEmail='', courseUrl='', policyUrl='', incidentUrl=''),
                 title='Handleiding {{APP_NAME}}', subtitle='Praktische hulp bij verantwoord gebruik', reviewedAt='',
                 visibility=dict(chapters={}, topics={}, errors=True, categories={'appendix-errors': False}, articles={}), sections=sections, errorCategories=categories)
    profile = dict(organization=dict(appName='LAICA', name='Provincie Limburg', helpdeskEmail='helpdesk@prvlimburg.nl', aiEmail='ai@prvlimburg.nl', trainingEmail='Limburgacademie@prvlimburg.nl', courseUrl='https://provincielimburg.studytube.nl/courses/435552/de-nationale-ai-cursus'),
                   reviewRequired=['DPIA', 'juridische compliance', 'datalocatie', 'leveranciers', 'logging', 'beheerdersinzage', 'bewaartermijnen', 'modeltraining', 'kosten', 'beschikbaarheid'],
                   note='Profielgegevens controleren vóór publicatie; geen geverifieerde beleidsgaranties.')
    # Compose replaces /app/defaults with this tracked directory. Keep both build contexts equal.
    # Compatibility tombstone; the actual content must not be served as a public asset.
    tombstone = dict(title='Handleiding', subtitle='', sections=[])
    payloads = {'manual.json': model, 'manual-limburg.json': profile, 'help-content.json': tombstone}
    for folder in [DEST, ROOT / 'overlay/defaults']:
        for name, value in payloads.items():
            text = json.dumps(value, ensure_ascii=False, indent=2) + '\n'
            path = folder / name
            if check:
                if not path.exists() or path.read_text() != text: raise SystemExit(f'Defaultinhoud niet actueel: {path.relative_to(ROOT)}')
            else:
                folder.mkdir(parents=True, exist_ok=True)
                path.write_text(text)
    print(f'Content {"check OK" if check else "gebouwd"}: {len(sections)} hoofdstukken, {sum(len(s["items"]) for s in sections)} topics, {sum(len(c["articles"]) for c in categories)} catalogusartikelen')


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true', help='Controleer beide defaultmappen zonder te schrijven')
    build(check=parser.parse_args().check)
